import{_ as e,o as a,c as o,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Tax types","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tax types | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/tax-types"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tax types | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/tax-types"}]]},"headers":[],"relativePath":"user-guide/tax-types.md","filePath":"user-guide/tax-types.md","lastUpdated":1787680328000}'),r={name:"user-guide/tax-types.md"};function i(s,t,d,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="tax-types" tabindex="-1">Tax types <a class="header-anchor" href="#tax-types" aria-label="Permalink to &quot;Tax types&quot;">​</a></h1><p>Configure <strong>sales tax</strong> and <strong>withholding tax</strong> rules for your workspace when the <strong>Accounting</strong> module is installed.</p><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;Where to find it&quot;">​</a></h2><p>Finance → <strong>Tax types</strong> (requires <code>accounting.view</code>).</p><h2 id="tax-type-kinds" tabindex="-1">Tax type kinds <a class="header-anchor" href="#tax-type-kinds" aria-label="Permalink to &quot;Tax type kinds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Direction</th><th>Used on</th></tr></thead><tbody><tr><td>Sales tax</td><td>Add on sale</td><td>Invoice, credit note, quotation, estimate, and purchase order lines</td></tr><tr><td>Withholding</td><td>Deduct on payment in</td><td>Customer payments (tax withheld by the customer)</td></tr><tr><td>Withholding</td><td>Deduct on payment out</td><td>Expense pay (tax you withhold from a vendor)</td></tr></tbody></table><p>Each tax type has a fixed <strong>rate</strong> (%), optional <strong>authority reference</strong> (free text for your jurisdiction’s section or code), and optional GL account mapping.</p><h2 id="starter-gl-accounts" tabindex="-1">Starter GL accounts <a class="header-anchor" href="#starter-gl-accounts" aria-label="Permalink to &quot;Starter GL accounts&quot;">​</a></h2><p>When Accounting is first used, these system accounts are seeded (or backfilled):</p><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Role</th></tr></thead><tbody><tr><td><code>2100</code></td><td>Tax Payable</td><td>Sales tax liability on invoices</td></tr><tr><td><code>1150</code></td><td>Withholding Tax Receivable</td><td>Customer withholding on payments</td></tr><tr><td><code>2150</code></td><td>Withholding Tax Payable</td><td>Vendor withholding on expense pay</td></tr></tbody></table><p>Map tax types to these accounts (or your own liability/asset accounts) on each tax type record.</p><h2 id="sales-tax-on-billing-documents" tabindex="-1">Sales tax on billing documents <a class="header-anchor" href="#sales-tax-on-billing-documents" aria-label="Permalink to &quot;Sales tax on billing documents&quot;">​</a></h2><p>On invoice and related line editors, pick an active <strong>sales tax</strong> type or enter a manual rate. When a tax type is selected, its rate is applied automatically.</p><p>When an invoice is <strong>sent</strong> (with Accounting installed), the accrual journal splits:</p><ul><li><strong>Dr</strong> Accounts Receivable (total)</li><li><strong>Cr</strong> Revenue (subtotal)</li><li><strong>Cr</strong> Tax Payable (tax total)</li></ul><h2 id="withholding-on-customer-payments" tabindex="-1">Withholding on customer payments <a class="header-anchor" href="#withholding-on-customer-payments" aria-label="Permalink to &quot;Withholding on customer payments&quot;">​</a></h2><p>On a payment, <strong>Amount</strong> is still the gross applied to AR. Withholding reduces the <strong>deposit</strong> only.</p><p>Example: $1,000 payment with 4% withholding → deposit $960, WHT receivable $40, AR credit $1,000.</p><p>Optional <strong>authority reference</strong> can be stored on the payment (copied from the tax type when blank).</p><h2 id="withholding-on-expense-pay" tabindex="-1">Withholding on expense pay <a class="header-anchor" href="#withholding-on-expense-pay" aria-label="Permalink to &quot;Withholding on expense pay&quot;">​</a></h2><p>When marking an expense paid, gross expense (amount + tax) is debited to the expense account. Cash credited is <strong>net of withholding</strong>; the withheld portion credits WHT Payable.</p><h2 id="counterparty-defaults" tabindex="-1">Counterparty defaults <a class="header-anchor" href="#counterparty-defaults" aria-label="Permalink to &quot;Counterparty defaults&quot;">​</a></h2><ul><li><strong>Contacts</strong> — default withholding type for customer payments (payment in).</li><li><strong>Vendors</strong> — default withholding type for expense pay (payment out).</li></ul><p>These pre-fill payment and expense pay forms when the contact or vendor is selected.</p><h2 id="workspace-tax-profile" tabindex="-1">Workspace tax profile <a class="header-anchor" href="#workspace-tax-profile" aria-label="Permalink to &quot;Workspace tax profile&quot;">​</a></h2><p>Settings → General (optional, for PDFs and reports):</p><ul><li><strong>Tax country</strong> — ISO 3166-1 alpha-2</li><li><strong>Tax registration ID</strong> — your workspace tax identifier</li></ul><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="/user-guide/accounting-overview">Accounting overview</a></li><li><a href="/user-guide/invoices-overview">Invoices</a></li><li><a href="/user-guide/payments-overview">Payments</a></li><li><a href="/user-guide/expenses-overview">Expenses</a></li></ul>',29)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
